@spec sample_page_spec  src=tests/specs/sample_page_spec.lua  loc=141  cases=7
@exercises commandManager (h.cmgr)
@surface   cmgr:installManifest, cmgr:scope
@harness   mk

# Intent
  Pin-tests for samplePage's Page interface (bind / unbind / focusState).
  Render methods pull in ImGui and are exercised manually in REAPER.
  
  samplePage requires ImGui at module scope; stub via package.preload
  before the first require so the module loads in the pure-Lua harness.

# Helpers
  @fn newSamplePage(cm, cmgr, chrome, gui, help)  @ 20-24

# Cases
  @case 'the manifest declares every command the sample page registers'  [harness]  @ 31-48
  @case 'every group the sample page places is one some scope declares'  [harness]  @ 54-69
  @case 'every bound command on the sample page has a place on the cheat-sheet'  [harness]  @ 75-94
  @case 'setTrack(track) re-keys cm to that track via the page's own sv'  [harness]  @ 98-106
  @case 'setTrack(nil) does not re-key cm'  [harness]  @ 109-117
  @case 'focusState before any render returns both bits false'  [harness]  @ 120-127
  @case 'bind re-keys cm to the page track on every activation, not just the first'  [harness]  @ 130-139

# Uses (outbound edges)
  @use call cmgr:installManifest  @ 38
  @use call cmgr:scope  @ 40

